		/* end MoveAw:R: */
		/* begin checkQuickConstant:forInstruction: */
		anInstruction1 = genoperandoperandoperand(MoveMwrR, 0, ClassReg, TempReg);
		/* end checkQuickConstant:forInstruction: */
		/* begin CmpR:R: */
